R,C=28,19
g=[[9]*C for _ in range(R)]
coords=[(2,4),(2,15),(3,4),(4,4),(6,4),(6,15),(8,4),(9,4),(10,15),(12,15),(13,4),(17,4),(18,15),(19,4),(23,4),(23,5),(23,6),(23,7),(23,11)]
for r,c in coords:g[r][c]=8
out=[row[:] for row in g]
for r in range(R):
 cs=[c for c in range(C) if g[r][c]==8]
 if len(cs)>1:
  for c in range(min(cs),max(cs)+1):
   if out[r][c]==9:out[r][c]=2
for c in range(C):
 rs=[r for r in range(R) if g[r][c]==8]
 if len(rs)>1:
  for r in range(min(rs),max(rs)+1):
   if out[r][c]==9:out[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out))

out2=[row[:] for row in g]
# Complete the lattice lines: two vertical rails and three horizontal bars.
for r in range(2,24):
 for c in (4,15):
  if out2[r][c]==9:out2[r][c]=2
for r in (2,6,23):
 for c in range(4,16):
  if out2[r][c]==9:out2[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out2))

out3=[row[:] for row in g]
# bridge the clearly identified vertical traces
for c in (4,15):
 rs=[r for r in range(R) if g[r][c]==8]
 for r in range(min(rs),max(rs)+1):
  if out3[r][c]==9:out3[r][c]=2
# top horizontal connector (the upper endpoints), plus the separate multi-mark row trace
for r,lo,hi in [(2,4,15),(23,4,11)]:
 for c in range(lo,hi+1):
  if out3[r][c]==9:out3[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out3))

out4=[row[:] for row in g]
# Fill only short gaps (up to four empty cells) between same-line marks.
for r in range(R):
 cs=[c for c in range(C) if g[r][c]==8]
 for a,b in zip(cs,cs[1:]):
  if b-a-1<=4:
   for c in range(a+1,b):out4[r][c]=2
for c in range(C):
 rs=[r for r in range(R) if g[r][c]==8]
 for a,b in zip(rs,rs[1:]):
  if b-a-1<=4:
   for r in range(a+1,b):out4[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out4))

out7=[row[:] for row in g]
for c in (4,15):
 rs=[r for r in range(R) if g[r][c]==8]
 for r in range(min(rs),max(rs)+1):
  if out7[r][c]==9: out7[r][c]=2
# row 23 has a genuine multi-mark horizontal segment
for c in range(4,12):
 if out7[23][c]==9:out7[23][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out7))

